using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Geometry;
using Autodesk.AutoCAD.Runtime;
using MedGas2024.Engine;
[assembly:CommandClass(typeof(VisibilityRuntimeTests))]
public static class VisibilityRuntimeTests
{
    static List<string> log=new List<string>();static void Check(bool ok,string text){if(!ok)throw new System.Exception(text);log.Add("PASS: "+text);}
    static bool Reject(Action a){try{a();return false;}catch(InvalidOperationException){return true;}}
    static ObjectId Layer(Database db,string name){using(var tr=db.TransactionManager.StartTransaction()){var t=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForWrite);var l=new LayerTableRecord{Name=name};t.Add(l);tr.AddNewlyCreatedDBObject(l,true);tr.Commit();return l.ObjectId;}}
    static ObjectId Pipe(Database db,ObjectId layer){using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var b=(BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);var e=new Line(Point3d.Origin,new Point3d(200,40,0));b.AppendEntity(e);tr.AddNewlyCreatedDBObject(e,true);e.LayerId=layer;e.LinetypeScale=.25;tr.Commit();return e.ObjectId;}}
    static void Flags(Database db,ObjectId id,bool off,bool frozen,bool locked=false){using(var tr=db.TransactionManager.StartTransaction()){var l=(LayerTableRecord)tr.GetObject(id,OpenMode.ForWrite);l.IsOff=off;l.IsFrozen=frozen;l.IsLocked=locked;tr.Commit();}}
    static bool State(Database db,ObjectId id,bool off,bool frozen,bool locked=false){using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var l=(LayerTableRecord)tr.GetObject(id,OpenMode.ForRead);return l.IsOff==off&&l.IsFrozen==frozen&&l.IsLocked==locked;}}
    [CommandMethod("MRTVISIBILITYTEST",CommandFlags.Modal)]public static void Run(){log.Clear();var previous=HostApplicationServices.WorkingDatabase;string root=Directory.GetParent(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location)).FullName;try{using(var db=new Database(true,true)){
        HostApplicationServices.WorkingDatabase=db;var source=Layer(db,"SOURCE");var off=Layer(db,"OFF_TARGET");var frozen=Layer(db,"FROZEN_TARGET");var locked=Layer(db,"LOCKED");var untouched=Layer(db,"UNTOUCHED");var p=Pipe(db,source);var p2=Pipe(db,source);var f=Pipe(db,frozen);var l=Pipe(db,locked);Flags(db,off,true,false);Flags(db,frozen,false,true);Flags(db,locked,true,false,true);
        var row=DrawingService.Read(db).Single(r=>r.LayerName=="OFF_TARGET");Check(row.CanAssign&&!row.Writable,"Off Layer is assignable while definition editing remains disabled");var assigned=DrawingService.Assign(db,new[]{p},"OFF_TARGET",true,true,1,expected:row);Check(assigned.Changed==1&&assigned.AssignedIds.SequenceEqual(new[]{p})&&State(db,off,true,false),"Assignment succeeds to an off Layer without changing its visibility");
        assigned=DrawingService.Assign(db,new[]{p},"OFF_TARGET",true,true,1);Check(assigned.Unchanged==1&&assigned.AssignedIds.SequenceEqual(new[]{p}),"Already-correct pipe is retained as a valid source for post-assignment isolation");
        assigned=DrawingService.Assign(db,new[]{p2},"FROZEN_TARGET",false,true,1);Check(assigned.Changed==1&&State(db,frozen,false,true),"Assignment to a frozen Layer preserves frozen state until isolation");Check(Reject(()=>DrawingService.Assign(db,new[]{p},"LOCKED",false,true,1)),"Locked target is rejected rather than unlocked");
        Check(Reject(()=>IsolationLayers.Open(db,new[]{p,f,l},true))&&!IsolationLayers.HasPending(db)&&State(db,off,true,false)&&State(db,frozen,false,true)&&State(db,locked,true,false,true),"Injected failure rolls back Layer flags and restoration data together");
        Check(IsolationLayers.Open(db,new[]{p,f,l})==3&&State(db,off,false,false)&&State(db,frozen,false,false)&&State(db,locked,false,false,true)&&IsolationLayers.HasPending(db),"Isolation preparation opens only required Layers while preserving locks");Check(Reject(()=>IsolationLayers.Open(db,new[]{p})),"A second preparation cannot overwrite the saved original flags");Flags(db,untouched,true,false);Check(IsolationLayers.Restore(db)==0&&State(db,off,true,false)&&State(db,frozen,false,true)&&State(db,locked,true,false,true)&&State(db,untouched,true,false)&&!IsolationLayers.HasPending(db),"Restore returns only touched flags and preserves unrelated user Layer changes");Check(IsolationLayers.Restore(db)==0,"Repeated end-isolation is harmless");
        IsolationLayers.Open(db,new[]{f});db.Clayer=frozen;Check(IsolationLayers.Restore(db)==1&&IsolationLayers.HasPending(db)&&State(db,frozen,false,false),"Current Layer cannot be refrozen; its pending restore is retained");db.Clayer=source;Check(IsolationLayers.Restore(db)==0&&State(db,frozen,false,true),"Switching current Layer permits the deferred restore");
        IsolationLayers.Open(db,new[]{p,f});string file=Path.Combine(root,"evidence","visibility-regression.dwg");db.SaveAs(file,DwgVersion.AC1032);using(var reopened=new Database(false,true)){reopened.ReadDwgFile(file,FileOpenMode.OpenForReadAndAllShare,true,null);HostApplicationServices.WorkingDatabase=reopened;Check(IsolationLayers.HasPending(reopened)&&IsolationLayers.Restore(reopened)==0,"Restore state survives save and reopen in a different Database instance");HostApplicationServices.WorkingDatabase=db;}
        IsolationLayers.Restore(db);using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var e=(Line)tr.GetObject(p,OpenMode.ForRead);Check(e.StartPoint==Point3d.Origin&&e.EndPoint==new Point3d(200,40,0)&&e.LinetypeScale==.25,"Assignment and Layer visibility leave geometry and retained scale intact");}
    }log.Add("RESULT: PASS; scratch Database only. Native ISOLATEOBJECTS/UNISOLATEOBJECTS and viewport/Undo require live tests.");}catch(System.Exception ex){log.Add("RESULT: FAIL");log.Add(ex.ToString());}finally{HostApplicationServices.WorkingDatabase=previous;File.WriteAllLines(Path.Combine(root,"evidence","visibility-runtime-tests.txt"),log);var doc=Autodesk.AutoCAD.ApplicationServices.Core.Application.DocumentManager.MdiActiveDocument;if(doc!=null)doc.Editor.WriteMessage("\n"+String.Join("\n",log)+"\n");}}
}
